def for_plant(code):
    m = MAP[code]
    name, over = (m, {}) if isinstance(m, str) else m
    d = {**PROFILES[name], **over}
    d = {k: (v if not isinstance(v, list) else '\n'.join(v)) for k, v in d.items()}
    d['pests_current'] = PESTS_NOW.get(code, PESTS_NOW_DEFAULT)
    return d

# ---- feeding season by profile: (first month, last month, days between feedings). Months wrap (10, 4 means October to April).
# Central Texas: last frost about mid-March, first frost about mid-November. Warm-season growers are fed while they grow
# and rested in the cool months; Aeonium grows in the cool season and rests in summer heat.
FERT_RULES = {
 'aroid': (3, 9, 21), 'aroid_low': (4, 9, 42), 'zz': (3, 8, 56), 'alocasia': (4, 9, 14), 'calathea': (3, 9, 28),
 'begonia': (3, 10, 21), 'fern': (4, 9, 28), 'palm': (3, 9, 42), 'orchid_phal': (3, 10, 14), 'vanilla': (3, 9, 14),
 'tree_trop': (3, 9, 30), 'fig': (3, 8, 30), 'grape': (3, 6, 30), 'vine_sun': (3, 9, 30), 'moringa': (4, 9, 30),
 'bougain': (3, 9, 28), 'cactus': (4, 8, 30), 'moon': (5, 9, 30), 'agave': (4, 9, 56), 'aloe': (4, 8, 42),
 'haworthia': (4, 9, 56), 'succulent': (4, 9, 42), 'aeonium': (10, 4, 42), 'adenium': (4, 9, 28), 'rose': (3, 9, 28),
 'annual': (3, 10, 14), 'coleus': (3, 10, 14), 'tradescantia': (3, 10, 28), 'hyacinth': (4, 9, 28), 'gardenia': (3, 9, 28),
 'grass': (3, 7, 56), 'iris': (3, 5, 56), 'unknown': (4, 9, 42),
}
def fert_for(code):
    m = MAP[code]
    name = m if isinstance(m, str) else m[0]
    over = {} if isinstance(m, str) else m[1]
    a, b, e = FERT_RULES[name]
    return {'fert_from_month': over.get('fert_from_month', a), 'fert_to_month': over.get('fert_to_month', b), 'fert_every_days': over.get('fert_every_days', e)}
